function normHex(v, bytes) {
  if (v == null) return null;
  var s = String(v).toLowerCase();
  if (s.indexOf('0x') === 0) { s = s.substring(2); }
  var need = bytes * 2;
  if (s.length > need) { s = s.substring(s.length - need); }
  while (s.length < need) { s = '0' + s; }
