      var off = (c * 8 + b) * 8;
      var st = parseInt(h.substring(off, off + 4), 16);
      var en = parseInt(h.substring(off + 4, off + 8), 16);
      if (st > 0 || en > 0) { vals.push(st + '-' + en); }
